package main
import("bytes";"fmt";"io";"net/http";"os";"strings";"time";"github.com/golang-jwt/jwt/v5";"gorm.io/driver/sqlite";"gorm.io/gorm";"webbuilder/internal/database/models")
func main(){db,_:=gorm.Open(sqlite.Open("../../../data/webbuilder.db"),&gorm.Config{});var u models.User;db.First(&u);var p models.Project;db.Where("user_id = ?",u.ID).Order("id DESC").First(&p);sec,_:=os.ReadFile("../../../.jwt-secret");t:=jwt.NewWithClaims(jwt.SigningMethodHS256,jwt.MapClaims{"uid":u.ID,"exp":time.Now().Add(time.Hour).Unix()});tok,_:=t.SignedString([]byte(strings.TrimSpace(string(sec))));base:=fmt.Sprintf("http://127.0.0.1:18082/api/projects/%d/runtime/dev",p.ID);call:=func(method,path string){req,_:=http.NewRequest(method,base+path,bytes.NewReader([]byte(`{}`)));req.Header.Set("Authorization","Bearer "+tok);req.Header.Set("Content-Type","application/json");r,e:=http.DefaultClient.Do(req);if e!=nil{panic(e)};o,_:=io.ReadAll(r.Body);r.Body.Close();fmt.Printf("%s %d %s\n",path,r.StatusCode,string(o))};call("POST","/start");time.Sleep(3*time.Second);call("GET","/status");call("GET","/logs");
	streamReq,_:=http.NewRequest("GET",base+"/log-stream",nil);streamReq.Header.Set("Authorization","Bearer "+tok);streamResp,streamErr:=http.DefaultClient.Do(streamReq);if streamErr==nil{buf:=make([]byte,256);n,_:=streamResp.Body.Read(buf);streamResp.Body.Close();fmt.Printf("/log-stream %d %s\\n",streamResp.StatusCode,string(buf[:n]))}else{fmt.Println("/log-stream ERR",streamErr)}
	call("GET","/preview/");call("POST","/stop")}
